WHERE u.tenant_id = #{tenantId}
  AND u.user_id = #{userId}
  AND u.use_at = 'Y'

SELECT COUNT(*)
FROM tb_user
WHERE tenant_id = #{tenantId}
  AND employee_no = #{employeeNo}

  AND user_id != #{excludeUserId}

SELECT COUNT(*)
FROM tb_user
WHERE tenant_id = #{tenantId}
  AND email_addr = #{emailAddr}

  AND user_id != #{excludeUserId}

SELECT COUNT(*)
FROM tb_user
WHERE tenant_id = #{tenantId}
  AND resident_no_hash = #{residentNoHash}

  AND user_id != #{excludeUserId}

SELECT COUNT(*)
FROM tb_login_account
WHERE tenant_id = #{tenantId}
  AND login_code = #{loginCode}

SELECT EXISTS (
    SELECT 1
    FROM tb_department
    WHERE tenant_id = #{tenantId}
      AND department_id = #{departmentId}
      AND use_at = 'Y'
)

SELECT EXISTS (
    SELECT 1
    FROM tb_common_code_item i
    JOIN tb_common_code_group g ON g.common_code_group_id = i.group_id
    WHERE g.tenant_id = #{tenantId}
      AND g.group_code = #{groupCode}
      AND g.use_at = 'Y'
      AND i.item_code = #{itemCode}
      AND i.use_at = 'Y'
)

SELECT EXISTS (
    SELECT 1
    FROM tb_common_code_item i
    JOIN tb_common_code_group g ON g.common_code_group_id = i.group_id
    WHERE g.tenant_id = #{tenantId}
      AND g.group_code = 'LEVEL'
      AND g.use_at = 'Y'
      AND i.common_code_item_id = #{levelId}
      AND i.use_at = 'Y'
)

INSERT INTO tb_login_account (
    tenant_id, login_code, password_hash, profile_image, password_changed_at, use_at
) VALUES (
    #{tenantId}, #{loginCode}, #{passwordHash}, #{profileImage,jdbcType=VARCHAR}, NULL, 'Y'
)
RETURNING login_id

